// mode: runOnceForEachItem — this node runs once PER SOP (12 times total).
// $input.item is THIS run's single item (not $input.first()/$input.all(),
// which belong to the "run once for all items" mode and would silently
// collapse all 12 SOPs down to just item 0).
//
// httpRequest with return=representation responds with an array containing
// the upserted row for this item.
const resp = $input.item.json;
const row = Array.isArray(resp) ? resp[0] : resp;

if (!row || !row.id) {
  throw new Error('Upsert SOP document returned no id: ' + JSON.stringify(resp));
}

return {
  json: {
    documentId: row.id,
    slug: row.slug,
    title: row.title,
    content: `${row.title}\n\n${row.body}`
  }
};

// mode: runOnceForEachItem — runs once PER SOP. $input.item is this run's
// single item, and $('Prepare for Embedding').item reads the matching
// paired item from that earlier node (NOT .first(), which would always be
// item 0 of the whole batch regardless of which item this run is on).
const resp = $input.item.json;
const values = resp.embedding && resp.embedding.values;
if (!Array.isArray(values) || values.length === 0) {
  throw new Error('Gemini embedding response missing embedding.values: ' + JSON.stringify(resp));
}

const doc = $('Prepare for Embedding').item.json;
return {
  json: {
    documentId: doc.documentId,
    slug: doc.slug,
    content: doc.content,
    embedding: values
  }
};

// mode: runOnceForAllItems — this node explicitly waits for and receives
// every item from the previous node in one execution, so $input.all() here
// is guaranteed to contain all 12 SOPs, never just one.
const items = $input.all().map(i => i.json);
return [{
  json: {
    status: 'ok',
    indexed: items.length,
    slugs: items.map(i => i.slug)
  }
}];
